/*
 * Drawing a QR code onto the panel.
 *
 * The QR code is generated by the espressif/qrcode component and rendered
 * with a callback, so this module only has to decide how big each module
 * should be and where the code goes.
 */

#include <string.h>

#include "esp_log.h"
#include "qrcode.h"

#include "drawing.h"
#include "epaper.h"
#include "qr.h"

static const char *TAG = "qr";

/**
 * Where the current QR code is being drawn.
 */
typedef struct {
    uint8_t *buffer;
    int width;
    int height;
    int x;
    int y;
    int target_size;
} qr_context_t;

static qr_context_t s_context;

/**
 * The callback the QR generator calls once the code is ready.
 */
static void qr_draw_callback(esp_qrcode_handle_t qrcode) {
    const qr_context_t *ctx = &s_context;
    int modules = esp_qrcode_get_size(qrcode);
    if (modules <= 0) {
        return;
    }

    /* Scale the modules so the code fills the target area exactly. Integer
     * scaling is avoided because it leaves ragged edges; a fractional
     * scale gives a clean, even code. */
    float module_size = (float)ctx->target_size / (float)modules;

    for (int qy = 0; qy < modules; qy++) {
        int y0 = ctx->y + (int)(qy * module_size);
        int y1 = ctx->y + (int)((qy + 1) * module_size);
        if (y1 <= y0) {
            y1 = y0 + 1;
        }

        for (int qx = 0; qx < modules; qx++) {
            if (!esp_qrcode_get_module(qrcode, qx, qy)) {
                continue;
            }

            int x0 = ctx->x + (int)(qx * module_size);
            int x1 = ctx->x + (int)((qx + 1) * module_size);
            if (x1 <= x0) {
                x1 = x0 + 1;
            }

            draw_fill_rect(ctx->buffer, ctx->width, ctx->height, x0, y0, x1 - x0, y1 - y0,
                           EPD_COLOR_BLACK);
        }
    }
}

/**
 * Draw a QR code.
 *
 * The code is drawn with a white margin around it, because a QR reader
 * needs a quiet zone to find the code's edges.
 *
 * @param buffer      The frame buffer.
 * @param width       The buffer width.
 * @param height      The buffer height.
 * @param x           The left edge.
 * @param y           The top edge.
 * @param size        The size of the code in pixels, excluding the margin.
 * @param text        The text to encode.
 *
 * @return true on success.
 */
bool qr_draw(uint8_t *buffer, int width, int height, int x, int y, int size, const char *text) {
    if (text == NULL || text[0] == '\0') {
        return false;
    }
    if (x < 0 || y < 0 || x + size > width || y + size > height) {
        ESP_LOGW(TAG, "The QR code does not fit at (%d, %d)", x, y);
        return false;
    }

    /* Clear the area first, including the quiet zone, so that whatever was
     * on the panel before does not show through. */
    const int margin = 4;
    int clear_x = x - margin;
    int clear_y = y - margin;
    int clear_w = size + margin * 2;
    int clear_h = size + margin * 2;

    /* Clip the clear to the buffer. */
    if (clear_x < 0) {
        clear_w += clear_x;
        clear_x = 0;
    }
    if (clear_y < 0) {
        clear_h += clear_y;
        clear_y = 0;
    }
    if (clear_x + clear_w > width) {
        clear_w = width - clear_x;
    }
    if (clear_y + clear_h > height) {
        clear_h = height - clear_y;
    }
    if (clear_w > 0 && clear_h > 0) {
        draw_fill_rect(buffer, width, height, clear_x, clear_y, clear_w, clear_h, EPD_COLOR_WHITE);
    }

    s_context.buffer = buffer;
    s_context.width = width;
    s_context.height = height;
    s_context.x = x;
    s_context.y = y;
    s_context.target_size = size;

    esp_qrcode_config_t config = {
        .display_func = qr_draw_callback,
        /* Version 10 is enough for a URL with a claim code in it, and keeps
         * the module count down so the code stays large on the panel. */
        .max_qrcode_version = 10,
        .qrcode_ecc_level = ESP_QRCODE_ECC_MED,
    };

    esp_err_t err = esp_qrcode_generate(&config, text);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to generate the QR code: %s", esp_err_to_name(err));
        return false;
    }

    return true;
}
